import { MapboxGeoJSONFeature } from "mapbox-gl";
import { Quality } from "./quality";
import { LatLngLiteral } from "leaflet";
export interface TerrainSource {
    maxZoom: number;
    tileSize: number;
    getSourceUrl: (params: {
        x: number;
        y: number;
        z: number;
    }) => string;
    getElevation: (params: {
        r: number;
        g: number;
        b: number;
        a: number;
    }) => number;
    _overzoom: number;
}
export interface DSMSource {
    data: Uint8ClampedArray;
    bounds: LatLngLiteral[];
    width: number;
    height: number;
    maxHeight: number;
}
export interface SunExposureOptions {
    startDate: Date;
    endDate: Date;
    iterations?: number;
}
export interface SunExposure extends SunExposureOptions {
    enabled: boolean;
}
export interface ShadeMapOptions {
    date?: Date;
    color?: string;
    opacity?: number;
    quality?: Quality;
    sunExposure?: SunExposure;
    terrainSource?: TerrainSource;
    canopySource?: TerrainSource;
    dsmSource?: DSMSource;
    getFeatures?: () => Promise<MapboxGeoJSONFeature[]>;
    apiKey: string;
    debug?: (msg: string) => void;
}
